#!/usr/bin/env bash
# Stvara oznake i Issue za svaki zahtjev. Potreban je GitHub CLI (gh) i "gh auth login".
set -e
REPO="Klik-Programsko-Inzinjerstvo/Programsko-Inzinjerstvo"

lbl(){ gh label create "$1" --color "$2" --repo "$REPO" --force >/dev/null; }
lbl "funkcijski" "1d76db"; lbl "nefunkcijski" "5319e7"; lbl "dokumentacija" "0e8a16"
lbl "frontend" "fbca04"; lbl "backend" "d93f0b"; lbl "baza" "c5def5"
lbl "prioritet: visok" "b60205"; lbl "prioritet: srednji" "e99695"; lbl "prioritet: nizak" "f9d0c4"

issue(){ gh issue create --repo "$REPO" --title "$1" --label "$2" --body "$3" >/dev/null; echo "  ✓ $1"; }

issue "[FZ-01] Pregled vremena i karte bez prijave" "funkcijski,prioritet: visok" "$(printf 'Akter: svi korisnici\n\nDetaljan opis i kriteriji prihvaćanja: [FZ-01](https://github.com/Klik-Programsko-Inzinjerstvo/Programsko-Inzinjerstvo/blob/main/docs/zahtjevi/funkcijski-zahtjevi.md#fz-01-pregled-vremena-i-karte-bez-prijave)')"
